(()=>{'use strict';const A=App,E=Engine,t=A.t,e=A.e;
A.exportTables=()=>{const p=A.p,report=Analyst.report(p,A.lang),a=report.analysis,bundle=report.bundle,ai=p.aiReport,stale=ai&&!report.active,selected=report.actions.map(o=>o.id);const headers=[t('Supplier','供应商'),t('Reference','编号'),t('Currency','币种'),t('Item subtotal','商品小计'),t('Discount','折扣'),t('Net items','税前净商品金额'),t('Shipping','运费'),t('Other fees','其他费用'),t('Tax','税额'),t('Landed cost','到手总成本'),t('Quoted days','报价交期'),t('Score','得分'),t('Eligibility','资格'),t('Reliability score','可靠性分数'),t('Reliability source','可靠性来源'),t('Prepayment','预付款'),t('Payment days','付款期限'),t('Valid until','有效期'),t('Source','来源')];const comparison=[headers,...a.rows.map(r=>[r.q.name,r.q.reference,r.q.currency,r.subtotal,r.discountAmount,r.net,r.shippingAmount,r.feesAmount,r.taxAmount,r.total,E.blank(r.q.days)?'':Number(r.q.days),r.score===null?'':Number(r.score.toFixed(4)),r.reasons.length?r.reasons.map(A.reason).join('; '):t('Eligible','合格'),r.reliability?.value??'',r.reliability?.source||'',r.prepayment??'',r.q.paymentDays,r.q.validUntil,r.q.source])];const lines=[[t('Supplier','供应商'),t('Product','产品'),'SKU',t('Specification','规格'),t('Unit','单位'),t('Quantity','数量'),t('Unit price','单价'),t('Line subtotal','行小计'),t('Currency','币种'),t('Prices include tax','单价含税'),t('Tax rate %','税率%'),t('MOQ','起订量')],...p.quotes.flatMap(q=>q.items.map(x=>[q.name,x.product,x.sku||'',x.specification||'',x.unit,Number(x.qty),Number(x.price),E.amount(E.multiply(x.qty,x.price,q.currency),q.currency),q.currency,q.taxIncluded,Number(q.tax),Number(x.moq)]))];const actions=[[t('Category','类别'),t('Action','行动'),t('Details','详情'),t('Fact IDs','事实编号')],...selected.map(id=>bundle.opportunities.find(o=>o.id===id)).filter(Boolean).map(o=>[o.section,o.title,o.body,o.factIds.join('; ')])];const facts=[['ID',t('Label','名称'),t('Value','值'),t('Unit','单位'),t('Supplier ID','供应商编号')],...bundle.facts.map(f=>[f.id,f.label,f.value,f.unit,f.supplierId])];const rules=[['QuotePilot','2.1'],['Report supplier',report.chosen?.q.name||''],['Report supplier total',report.chosen?.total??''],['Weighted leader',a.best?.q.name||''],['AI supporting fact IDs',report.reasonFactIds.join('; ')],[t('Project','项目'),p.name],[t('Exported at','导出时间'),new Date().toISOString()],[t('Currency','币种'),p.currency],[t('Budget','预算'),p.budget],[t('Comparable baseline','可比基准'),p.baseline],[t('Baseline less recommended cost (potential)','基准减推荐成本（潜在）'),report.baselineSavings],[t('Budget headroom','预算余量'),report.budgetMargin],[t('Eligible quote spread','可比报价差额'),a.spread],['Cost weight (normalized)',a.weights.cost],['Delivery weight (normalized)',a.weights.delivery],['Reliability weight (normalized)',a.weights.reliability],['Delivery target / zero-score day',p.targetDays+' / '+p.limitDays],['Delivery hard deadline',p.deadline],['Hard budget cap',p.budgetHard],['Rounding','Exact decimal; half-up per line and order component at currency precision'],['Cost scoring','Lowest eligible cost / quote cost × 100; zero-cost quote = 100'],['Delivery scoring','100 through target day; linear to 0 at zero-score day'],['Reliability','Entered evidence score or observed on-time count / total count × 100'],['Eligibility','Reviewed; same currency, product basket, units, quantities; MOQ/minimum value, expiry and hard constraints; data required for active criteria'],['Savings','Projected comparisons only, not realized savings'],['AI report',ai?(stale?'Stale AI snapshot excluded from current actions':'Validated AI action selection'):'Local deterministic actions'],['AI model',ai?.model||''],['Decision supplier',p.decision?.supplierName||''],['Decision amount',p.decision?.total??''],['Decision currency',p.decision?.currency||''],['Decision date',p.decision?.at||''],['Decision reason',p.decision?.reason||''],['Decision status',p.decision?(p.decision.fingerprint===E.fingerprint(p)?'Current':'Stale; review before use'):'Not recorded']];return {comparison,lines,actions,facts,rules,bundle,a,report};};
A.exportFile=type=>{const p=A.p,data=A.exportTables(),filename='QuotePilot-'+p.name.replace(/[^\p{L}\p{N}_-]/gu,'_').slice(0,60);if(type==='csv'){A.download(filename+'-comparison.csv',E.csv(data.comparison),'text/csv;charset=utf-8');return;}if(type==='xlsx'){const wb=XLSX.utils.book_new();for(const [name,rows]of Object.entries({Comparison:data.comparison,Items:data.lines,Recommendations:data.actions,Evidence:data.facts,Method_and_decision:data.rules})){const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=rows[0].map((_,i)=>({wch:Math.min(60,Math.max(16,...rows.map(r=>String(r[i]??'').length)))}));if(rows.length>1)ws['!autofilter']={ref:XLSX.utils.encode_range({s:{r:0,c:0},e:{r:rows.length-1,c:rows[0].length-1}})};XLSX.utils.book_append_sheet(wb,ws,name);}A.download(filename+'.xlsx',XLSX.write(wb,{type:'array',bookType:'xlsx'}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');return;}
 const table=rows=>`<table><thead><tr>${rows[0].map(v=>`<th>${e(v)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map(v=>`<td>${e(v??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;const compact=[data.comparison[0].filter((_,i)=>[0,2,6,7,8,9,10,11,12].includes(i)),...data.comparison.slice(1).map(r=>r.filter((_,i)=>[0,2,6,7,8,9,10,11,12].includes(i)))];const html=`<!doctype html><html lang="${A.lang}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(p.name)} · QuotePilot decision report</title><style>body{font:14px/1.6 system-ui,sans-serif;color:#182039;max-width:1100px;margin:40px auto;padding:0 24px}h1{font-size:35px;letter-spacing:-1px}h2{margin-top:35px}p{color:#60708a}table{width:100%;border-collapse:collapse;font-size:11px;display:block;overflow:auto}td,th{border:1px solid #dce1eb;padding:9px;text-align:left;vertical-align:top}th{background:#f0f2fc}section{border:1px solid #dce1eb;border-radius:12px;padding:20px;margin:20px 0}svg{width:100%;max-height:400px}.grid-line{stroke:#e3e7ee;stroke-width:1}.axis-text{font-size:11px;fill:#758096}.chart-label{font-size:12px;fill:#182039}.chart-value{font-size:12px;font-weight:600}.chart-legend{display:flex;gap:14px;font-size:11px}.chart-legend i{display:inline-block;width:8px;height:8px;margin-right:5px}.mobile-cost{display:none}button{padding:10px 18px;background:#4654ed;color:white;border:0;border-radius:7px;cursor:pointer}a{color:#4654ed}.small{font-size:12px}.notice{background:#f0f2fc;padding:15px;border-radius:8px}@media print{button{display:none}body{margin:0;max-width:none;padding:0}section{break-inside:avoid}table{display:table;font-size:9px}h2{break-after:avoid}}</style><button onclick="window.print()">${t('Print / save as PDF','打印 / 保存为PDF')}</button><p>QUOTEPILOT 2.1 · ${t('Procurement decision report','采购决策报告')}</p><h1>${e(p.name)}</h1><p>${e(p.description)}<br>${t('Prepared','生成时间')}: ${e(new Date().toLocaleString())} · ${e(p.currency)}</p><div class="notice">${t('Report recommendation','报告推荐')}: <strong>${e(data.report.chosen?.q.name||t('No supported recommendation','暂无有依据的推荐'))}</strong> · ${A.money(data.report.chosen?.total)}<br>${t('Eligible quote spread','可比报价差额')}: ${A.money(data.a.spread)} · ${t('Budget headroom','预算余量')}: ${A.money(data.report.budgetMargin)}<br>${t('Potential savings against entered baseline','相对输入基准的潜在节省')}: ${A.money(data.report.baselineSavings)}<br>${t('These are comparisons, not realized savings or a purchase approval.','上述为比较结果，并非已实现节省或采购审批。')}</div>${p.decision?`<section><h2>${t('Recorded decision','已记录决策')}</h2><p><b>${e(p.decision.supplierName)}</b> · ${A.money(p.decision.total,p.decision.currency)} · ${e(p.decision.at)}</p><p>${e(p.decision.reason)}</p><p>${p.decision.fingerprint===E.fingerprint(p)?t('Matches current data','与当前数据一致'):t('Stale snapshot. Recheck against current data.','过时快照，请对照当前数据重新审核。')}</p></section>`:''}<h2>${t('Cost comparison','成本比较')}</h2>${Charts.cost(data.a.eligible,{money:A.money,t}).replace(/ data-action="[^"]*"| tabindex="[^"]*"| role="button"/g,'')}${table(compact)}<h2>${t('Purchasing actions','采购行动')}</h2>${p.aiReport?`<p>${p.aiReport.fingerprint===E.fingerprint(p)?t('AI-prioritized, evidence-validated actions','AI排序、依据已校验的行动'):t('Saved AI report is stale; current local actions are shown.','已保存AI报告过时，显示当前本地行动。')}</p>`:''}${data.actions.slice(1).map(r=>`<section><p class="small">${e(r[0])}</p><h3>${e(r[1])}</h3><p>${e(r[2])}</p><p class="small">${t('Evidence','依据')}: ${e(r[3])}</p></section>`).join('')}<h2>${t('Calculation rules and decision record','计算规则及决策记录')}</h2>${table([['Field','Value'],...data.rules])}<h2>${t('Verified evidence','已核实依据')}</h2>${table(data.facts)}<p class="small">${t('Prepared locally in QuotePilot. Supplier data is user-provided; unknown reliability is never replaced with an invented rating.','由QuotePilot在本地生成。供应商数据由用户提供，未知可靠性不会被虚构评分替代。')}</p></html>`;A.download(filename+'-decision.html',html,'text/html;charset=utf-8');};
A.template=()=>{const p=E.sampleProject(),rows=[['Supplier','Product','SKU','Specification','Unit','Quantity','Unit price','Currency','Shipping','Discount %','Tax rate','Tax shipping','Delivery days','Prepayment %']];p.quotes.forEach(q=>q.items.forEach(x=>rows.push([q.name,x.product,x.sku||'',x.specification||'',x.unit,x.qty,x.price,q.currency,q.shipping,q.discount,q.tax,'yes',q.days,q.prepay])));const wb=XLSX.utils.book_new();const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=rows[0].map((_,i)=>({wch:i===1?38:18}));XLSX.utils.book_append_sheet(wb,ws,'Quotations');A.download('QuotePilot-v2-import-template.xlsx',XLSX.write(wb,{bookType:'xlsx',type:'array'}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');};
})();
